/**
 * Resource registry: single source of metadata for the shared enterprise data model.
 * Drives generic, validated, permission-checked, audited CRUD (crud.ts), the OpenAPI document,
 * global search and the metadata-driven UI (forms, tables, filters).
 * Domain behaviour that is more than CRUD lives in src/domain/* services and hooks referenced here.
 */
export type FieldType = 'text' | 'textarea' | 'int' | 'number' | 'money' | 'pct' | 'date' | 'datetime' | 'bool' | 'enum' | 'ref' | 'numarray';
export interface FieldDef {
  n: string; l?: string; t: FieldType; req?: boolean; opts?: string[]; ref?: string; list?: boolean; ro?: boolean;
  min?: number; max?: number; help?: string; def?: unknown;
}
export interface ResourceDef {
  key: string; table: string; label: string; plural: string; prefix: string; module: string;
  fields: FieldDef[];
  contexts?: string[];             // allowed context_type values (polymorphic parent)
  contextRequired?: boolean;
  hasCode?: boolean; hasName?: boolean; hasOwner?: boolean; hasStatus?: boolean;
  statusOptions?: string[];
  defaultSort?: string;
  searchable?: boolean;
  description?: string;
}

export const CONTEXT_TABLES: Record<string, string | null> = {
  enterprise: null, none: null, bau: null,
  portfolio: 'portfolios', programme: 'programmes', project: 'projects', product: 'products', service: 'services', idea: 'ideas',
};

const LEVEL = ['low', 'medium', 'high', 'critical'];
const f = (n: string, t: FieldType, extra: Partial<FieldDef> = {}): FieldDef => ({ n, t, ...extra });
const name = (l = 'Name') => f('name', 'text', { req: true, list: true, l });
const desc = f('description', 'textarea');
const owner = f('owner_id', 'ref', { ref: 'users', l: 'Owner', list: true });
const classification = f('classification', 'enum', { opts: ['public', 'internal', 'confidential', 'restricted'], def: 'internal' });

function res(d: Omit<ResourceDef, 'hasCode' | 'hasName' | 'hasOwner' | 'hasStatus' | 'searchable'> & Partial<ResourceDef>): ResourceDef {
  return { hasCode: true, hasName: true, hasOwner: true, hasStatus: true, searchable: true, defaultSort: 'created_at desc', ...d };
}

